import{_ as a,a as t,c as s,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"第一册：英语初阶 · 单元 6 复习与自测 · 第128–134课","description":"L121–L144 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 6 复习与自测 · 第128–134课","description":"L121–L144 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-06/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 6 复习与自测","summary":"L121–L144 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 6 复习与自测 · 第121–127课","link":"/life/english/new-concept/book-1/unit-06/review-part-01"},"next":{"text":"第一册：英语初阶 · 单元 6 复习与自测 · 第135–141课","link":"/life/english/new-concept/book-1/unit-06/review-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 6 复习与自测 · 第121–127课","link":"/life/english/new-concept/book-1/unit-06/review-part-01"},"next":{"text":"第一册：英语初阶 · 单元 6 复习与自测 · 第135–141课","link":"/life/english/new-concept/book-1/unit-06/review-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/review-part-02.md","filePath":"life/english/new-concept/book-1/unit-06/review-part-02.md"}'),o={name:"life/english/new-concept/book-1/unit-06/review-part-02.md"};function r(i,e,l,h,d,m){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-单元-6-复习与自测-·-第128–134课" tabindex="-1">第一册：英语初阶 · 单元 6 复习与自测 · 第128–134课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-6-复习与自测-·-第128–134课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 6 复习与自测 · 第128–134课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-06/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-06/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-128-·-must-cannot-表现在推断" tabindex="-1">Lesson 128 · must/cannot 表现在推断 <a class="header-anchor" href="#lesson-128-·-must-cannot-表现在推断" aria-label="Permalink to &quot;Lesson 128 · must/cannot 表现在推断 {#lesson-128-·-must-cannot-表现在推断}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> That cannot be our bus; it has a different number.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1 {#练习-1-7}&quot;">​</a></h3><p>表达不可能：That ___ be our bus.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> cannot / can&#39;t</p><p><strong>解析：</strong> 按本课规则判断：must be 在推断中表示根据证据很有把握，不能译为命令意义的“必须是”。can&#39;t be 表根据证据认为不可能；may/might be 表不确定的可能。推断应说明证据，不能把 must 当成证明。情态动词后用原形 be，即便主语是 he/she 也不改为 is。</p></details><p><strong>表达迁移：</strong> 围绕“根据线索推测身份或当前状态”写两至三句，再读给同伴听。至少使用一次must/cannot 表现在推断，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>That cannot be our bus; it has a different number. The office lights are on; someone must be inside.</p><p>Cannot be 表不可能是；分号后 different number 提供推断依据，its number 与 expected bus number 不同。 前半句灯亮着是观察线索；后半句 must be 是强推断，someone 是主语，inside 为地点表语。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-128">回看本课</a></p><h2 id="lesson-129-·-情态动词-have-done" tabindex="-1">Lesson 129 · 情态动词 + have done <a class="header-anchor" href="#lesson-129-·-情态动词-have-done" aria-label="Permalink to &quot;Lesson 129 · 情态动词 + have done {#lesson-129-·-情态动词-have-done}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The road is wet; it must have rained overnight.</p><h3 id="练习-1-8" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-8" aria-label="Permalink to &quot;练习 1 {#练习-1-8}&quot;">​</a></h3><p>填分词：It must have ___ (rain).</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> rained</p><p><strong>解析：</strong> 按本课规则判断：must have + 过去分词表示对过去的强推断，can&#39;t have + 过去分词表示认为过去不可能发生。它们不是现在完成时的普通肯否定，而是情态推断结构。过去状态用 have been，过去动作使用相应分词。速度等信息应作为证据，不要把猜测说成亲眼观察；本页只练语言，不判断实际交通责任。</p></details><p><strong>表达迁移：</strong> 围绕“根据现在的证据推测过去”写两至三句，再读给同伴听。至少使用一次情态动词 + have done，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The road is wet; it must have rained overnight. He cannot have read the sign; it was covered.</p><p>The road is wet 是现在证据；must have rained 对过去下雨作推断，overnight 指夜里。 Cannot have read 对过去是否读到标志作否定推断；it was covered 给出证据，但推断本身不是亲眼观察。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-129">回看本课</a></p><h2 id="lesson-130-·-情态动词-have-done" tabindex="-1">Lesson 130 · 情态动词 + have done <a class="header-anchor" href="#lesson-130-·-情态动词-have-done" aria-label="Permalink to &quot;Lesson 130 · 情态动词 + have done {#lesson-130-·-情态动词-have-done}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> He cannot have read the sign; it was covered.</p><h3 id="练习-1-9" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-9" aria-label="Permalink to &quot;练习 1 {#练习-1-9}&quot;">​</a></h3><p>选择 have/had：He cannot ___ read the sign.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 按本课规则判断：must have + 过去分词表示对过去的强推断，can&#39;t have + 过去分词表示认为过去不可能发生。它们不是现在完成时的普通肯否定，而是情态推断结构。过去状态用 have been，过去动作使用相应分词。速度等信息应作为证据，不要把猜测说成亲眼观察；本页只练语言，不判断实际交通责任。</p></details><p><strong>表达迁移：</strong> 围绕“根据现在的证据推测过去”写两至三句，再读给同伴听。至少使用一次情态动词 + have done，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>He cannot have read the sign; it was covered. The road is wet; it must have rained overnight.</p><p>Cannot have read 对过去是否读到标志作否定推断；it was covered 给出证据，但推断本身不是亲眼观察。 The road is wet 是现在证据；must have rained 对过去下雨作推断，overnight 指夜里。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-130">回看本课</a></p><h2 id="lesson-131-·-may-might-的时间层次" tabindex="-1">Lesson 131 · may/might 的时间层次 <a class="header-anchor" href="#lesson-131-·-may-might-的时间层次" aria-label="Permalink to &quot;Lesson 131 · may/might 的时间层次 {#lesson-131-·-may-might-的时间层次}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The parcel may arrive tomorrow.</p><h3 id="练习-1-10" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-10" aria-label="Permalink to &quot;练习 1 {#练习-1-10}&quot;">​</a></h3><p>填动词原形：The parcel may ___ (arrive).</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> arrive</p><p><strong>解析：</strong> 按本课规则判断：may/might + 原形表示现在或将来的可能，may/might have + 过去分词表示过去的可能。may be 是两词，maybe 是副词“也许”，不能在句法上直接互换。may not 意为可能不，通常不等于不可能；can&#39;t 才常用于有根据的排除。为保留不确定性，说明已知事实和猜测的界限。</p></details><p><strong>表达迁移：</strong> 围绕“讨论未确定的现在与过去可能”写两至三句，再读给同伴听。至少使用一次may/might 的时间层次，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The parcel may arrive tomorrow. Ella might have left her phone on the train.</p><p>May arrive 表未来可能，arrive 保持原形；tomorrow 表时间，整句不保证包裹一定到达。 Might have left 对过去遗落手机作不确定推断；on the train 说明可能遗落的地点。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-131">回看本课</a></p><h2 id="lesson-132-·-may-might-的时间层次" tabindex="-1">Lesson 132 · may/might 的时间层次 <a class="header-anchor" href="#lesson-132-·-may-might-的时间层次" aria-label="Permalink to &quot;Lesson 132 · may/might 的时间层次 {#lesson-132-·-may-might-的时间层次}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Ella might have left her phone on the train.</p><h3 id="练习-1-11" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-11" aria-label="Permalink to &quot;练习 1 {#练习-1-11}&quot;">​</a></h3><p>填分词：She might have ___ (leave) it on the train.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> left</p><p><strong>解析：</strong> 按本课规则判断：may/might + 原形表示现在或将来的可能，may/might have + 过去分词表示过去的可能。may be 是两词，maybe 是副词“也许”，不能在句法上直接互换。may not 意为可能不，通常不等于不可能；can&#39;t 才常用于有根据的排除。为保留不确定性，说明已知事实和猜测的界限。</p></details><p><strong>表达迁移：</strong> 围绕“讨论未确定的现在与过去可能”写两至三句，再读给同伴听。至少使用一次may/might 的时间层次，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Ella might have left her phone on the train. The parcel may arrive tomorrow.</p><p>Might have left 对过去遗落手机作不确定推断；on the train 说明可能遗落的地点。 May arrive 表未来可能，arrive 保持原形；tomorrow 表时间，整句不保证包裹一定到达。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-132">回看本课</a></p><h2 id="lesson-133-·-间接引语的时态回移" tabindex="-1">Lesson 133 · 间接引语的时态回移 <a class="header-anchor" href="#lesson-133-·-间接引语的时态回移" aria-label="Permalink to &quot;Lesson 133 · 间接引语的时态回移 {#lesson-133-·-间接引语的时态回移}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The reporter said that the bridge was closed.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>按回移练习转述：He said, &quot;I am busy.&quot;</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He said that he was busy.</p><p><strong>解析：</strong> 按本课规则判断：过去时 said/told 引出转述时，原话的一般现在时常回移为一般过去时，现在进行时常回移为过去进行时。代词要随说话者身份调整。如果事实仍然成立或属于普遍事实，英语也允许保留原时态；不是所有转述都必须回移。say 与 tell 的结构不同，told 后通常要有听话者。</p></details><p><strong>表达迁移：</strong> 围绕“转述过去听到的消息”写两至三句，再读给同伴听。至少使用一次间接引语的时态回移，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The reporter said that the bridge was closed. Maya told us that she was studying abroad.</p><p>Said 为过去引述，that 从句采用 was；the bridge 是从句主语，closed 为状态表语。 Told 后保留听话者 us；she was studying 是转述内容，其中过去进行时可对应原话的 am studying。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-133">回看本课</a></p><h2 id="lesson-134-·-间接引语的时态回移" tabindex="-1">Lesson 134 · 间接引语的时态回移 <a class="header-anchor" href="#lesson-134-·-间接引语的时态回移" aria-label="Permalink to &quot;Lesson 134 · 间接引语的时态回移 {#lesson-134-·-间接引语的时态回移}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Maya told us that she was studying abroad.</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>选择 said/told：Maya ___ us that she was studying.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> told</p><p><strong>解析：</strong> 按本课规则判断：过去时 said/told 引出转述时，原话的一般现在时常回移为一般过去时，现在进行时常回移为过去进行时。代词要随说话者身份调整。如果事实仍然成立或属于普遍事实，英语也允许保留原时态；不是所有转述都必须回移。say 与 tell 的结构不同，told 后通常要有听话者。</p></details><p><strong>表达迁移：</strong> 围绕“转述过去听到的消息”写两至三句，再读给同伴听。至少使用一次间接引语的时态回移，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Maya told us that she was studying abroad. The reporter said that the bridge was closed.</p><p>Told 后保留听话者 us；she was studying 是转述内容，其中过去进行时可对应原话的 am studying。 Said 为过去引述，that 从句采用 was；the bridge 是从句主语，closed 为状态表语。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-134">回看本课</a></p>',60)])])}const u=a(o,[["render",r]]);export{c as __pageData,u as default};
